o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Adenosine IV bolus', 'Аденозин внутривенно болюсно'), ('B', 'Atropine IV', 'Атропин внутривенно'), ('C', 'Oral digoxin', 'Дигоксин внутрь'), ('D', 'Synchronised cardioversion', 'Синхронизированная кардиоверсия')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'A', 'Regular narrow-complex tachycardia in a stable patient is most often an AV-nodal re-entrant tachycardia. After vagal manoeuvres fail, a rapid IV bolus of adenosine transiently blocks the AV node and usually terminates it. Synchronised cardioversion is reserved for unstable patients; atropine would accelerate the rate.', null, 'Key words: ''stable'', ''regular'', ''narrow''. That combination points to a re-entry circuit through the AV node, so the drug that briefly blocks the AV node is the logical next step. Instability would change the answer to electricity.' from q;

