insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'B', 'Light''s criteria classify an effusion as an exudate if ANY of the following is true: pleural/serum protein > 0.5, pleural/serum LDH > 0.6, or pleural LDH > two-thirds of the upper limit of normal for serum LDH. Options A, C and D all fall on the transudate side.', null, 'Remember the three numbers: 0.5 (protein ratio), 0.6 (LDH ratio), 2/3 (LDH vs upper limit). Only one option crosses a threshold.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-pulm-02', 'pulmonology', 1, 'A tall, thin 22-year-old man develops sudden right-sided pleuritic chest pain and breathlessness. On the right, breath sounds are absent and percussion is hyperresonant. What is the most likely diagnosis?', 'У высокого худощавого мужчины 22 лет внезапно возникли боль в правой половине грудной клетки, усиливающаяся при дыхании, и одышка. Справа дыхание не проводится, перкуторно — коробочный звук. Наиболее вероятный диагноз?', '[{"ru":"пневмоторакс","en":"pneumothorax"},{"ru":"коробочный звук","en":"hyperresonant percussion note"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Lobar pneumonia', 'Долевая пневмония'), ('B', 'Pleural effusion', 'Плевральный выпот'), ('C', 'Primary spontaneous pneumothorax', 'Первичный спонтанный пневмоторакс'), ('D', 'Pulmonary embolism', 'Тромбоэмболия лёгочной артерии')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'C', 'Primary spontaneous pneumothorax typically affects tall, thin young men without lung disease. Air in the pleural space gives absent breath sounds with a hyperresonant percussion note. Effusion and consolidation are dull to percussion.', null, 'Percussion is the discriminator: dull = fluid or consolidation; hyperresonant = air. Combine that with the classic patient profile.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-gi-01', 'gastroenterology', 2, 'A 64-year-old man has painless progressive jaundice, weight loss and a palpable, non-tender gallbladder. Which diagnosis is most likely?', 'У мужчины 64 лет безболевая нарастающая желтуха, снижение массы тела, пальпируется увеличенный безболезненный желчный пузырь. Наиболее вероятный диагноз?', '[{"ru":"симптом Курвуазье","en":"Courvoisier''s sign"},{"ru":"механическая желтуха","en":"obstructive jaundice"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Choledocholithiasis', 'Холедохолитиаз'), ('B', 'Carcinoma of the head of the pancreas', 'Рак головки поджелудочной железы'), ('C', 'Acute calculous cholecystitis', 'Острый калькулёзный холецистит'), ('D', 'Acute viral hepatitis A', 'Острый вирусный гепатит A')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'B', 'Courvoisier''s law: a palpable, non-tender gallbladder with painless jaundice is unlikely to be due to gallstones and suggests malignant obstruction of the distal common bile duct, classically carcinoma of the pancreatic head. Gallstone disease tends to cause a fibrosed, non-distensible gallbladder and painful episodes.', null, 'Painless + palpable gallbladder + weight loss is a red-flag triad. Ask yourself why stones rarely produce a distended gallbladder.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-gi-02', 'gastroenterology', 2, 'A patient with a duodenal ulcer tests positive for Helicobacter pylori. In a region with low clarithromycin resistance, which first-line regimen is appropriate?', 'У пациента с язвой двенадцатиперстной кишки выявлен Helicobacter pylori. В регионе с низкой резистентностью к кларитромицину какая схема первой линии целесообразна?', '[{"ru":"эрадикация","en":"eradication"},{"ru":"ингибитор протонной помпы (ИПП)","en":"proton pump inhibitor (PPI)"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Proton pump inhibitor alone for 8 weeks', 'Монотерапия ингибитором протонной помпы 8 недель'), ('B', 'Amoxicillin alone for 7 days', 'Монотерапия амоксициллином 7 дней'), ('C', 'PPI + clarithromycin + amoxicillin for 14 days', 'ИПП + кларитромицин + амоксициллин 14 дней'), ('D', 'H2-receptor blocker + antacid', 'Блокатор H2-рецепторов + антацид')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'C', 'Where clarithromycin resistance is low, standard triple therapy (PPI + clarithromycin + amoxicillin) for 14 days is an accepted first-line regimen; bismuth quadruple therapy is the usual alternative. Monotherapy does not eradicate H. pylori. Always follow current national guidelines.', null, 'Eradication needs acid suppression plus two antibiotics. Single agents fail because of resistance and low gastric drug activity.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-endo-01', 'endocrinology', 2, 'A 19-year-old with type 1 diabetes presents with vomiting, Kussmaul breathing, glucose 28 mmol/L and pH 7.1. What is the most important first step in management?', 'Пациент 19 лет с сахарным диабетом 1 типа поступил с рвотой, дыханием Куссмауля, глюкозой 28 ммоль/л и pH 7,1. Какое первоочередное мероприятие наиболее важно?', '[{"ru":"диабетический кетоацидоз","en":"diabetic ketoacidosis"},{"ru":"дыхание Куссмауля","en":"Kussmaul breathing"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'IV 0.9% sodium chloride', 'Внутривенное введение 0,9% раствора натрия хлорида'), ('B', 'Routine IV sodium bicarbonate', 'Рутинное внутривенное введение натрия гидрокарбоната'), ('C', 'Subcutaneous insulin glargine', 'Подкожное введение инсулина гларгин'), ('D', 'Oral rehydration solution', 'Пероральная регидратация')) as v(p, en, ru))
