with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-endo-02', 'endocrinology', 1, 'Which laboratory pattern is typical of primary hypothyroidism?', 'Какие лабораторные показатели характерны для первичного гипотиреоза?', '[{"ru":"гипотиреоз","en":"hypothyroidism"},{"ru":"тиреотропный гормон (ТТГ)","en":"thyroid-stimulating hormone (TSH)"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Low TSH, high free T4', 'ТТГ снижен, свободный T4 повышен'), ('B', 'High TSH, low free T4', 'ТТГ повышен, свободный T4 снижен'), ('C', 'Low TSH, low free T4', 'ТТГ снижен, свободный T4 снижен'), ('D', 'Normal TSH, high free T4', 'ТТГ в норме, свободный T4 повышен')) as v(p, en, ru))
