insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'A', 'An expanding annular rash with central clearing after a tick bite is erythema migrans, the hallmark of early Lyme borreliosis. Doxycycline is first-line for adults; amoxicillin is an alternative (e.g. in pregnancy). Antivirals, antifungals and metronidazole have no role.', null, 'Erythema migrans is a clinical diagnosis — serology is often negative this early. Treat the spirochaete.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-inf-02', 'infectious-diseases', 2, 'A traveller returning from sub-Saharan Africa has high fever and confusion. A thin blood film shows numerous ring forms. Which species is most likely?', 'У путешественника, вернувшегося из Африки южнее Сахары, высокая лихорадка и спутанность сознания. В тонком мазке крови — многочисленные кольцевидные формы. Какой вид возбудителя наиболее вероятен?', '[{"ru":"тропическая малярия","en":"falciparum malaria"},{"ru":"тонкий мазок крови","en":"thin blood film"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
