insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'D', 'Plasmodium falciparum causes severe malaria, including cerebral malaria (confusion, coma). It produces high parasitaemia with multiple ring forms per red cell and is the dominant species in sub-Saharan Africa. It is a medical emergency.', null, 'Confusion + travel to sub-Saharan Africa + many rings = treat as severe falciparum malaria until proven otherwise.' from q;

