with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-neuro-02', 'neurology', 2, 'A right-handed man suddenly develops right-sided weakness affecting the face and arm more than the leg, with non-fluent speech but preserved comprehension. Which vascular territory is affected?', 'У мужчины-правши внезапно развилась слабость в правых конечностях (рука и лицо больше, чем нога), речь прерывистая, с трудом подбирает слова, понимание обращённой речи сохранено. Какой сосудистый бассейн поражён?', '[{"ru":"моторная афазия","en":"expressive (Broca''s) aphasia"},{"ru":"гемипарез","en":"hemiparesis"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Right middle cerebral artery', 'Правая средняя мозговая артерия'), ('B', 'Left middle cerebral artery', 'Левая средняя мозговая артерия'), ('C', 'Left anterior cerebral artery', 'Левая передняя мозговая артерия'), ('D', 'Basilar artery', 'Основная артерия')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'B', 'Face and arm weakness greater than leg weakness indicates the middle cerebral artery territory. Expressive (Broca''s) aphasia means the dominant hemisphere is involved — the left in nearly all right-handed people. Contralateral signs place the lesion in the left MCA.', null, 'Two steps: (1) which side? opposite to the weakness; (2) which artery? face + arm > leg is MCA, leg > arm is ACA.' from q;

