insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'A', 'Uterine atony accounts for the large majority of primary postpartum haemorrhage. The ''four Ts'' — Tone, Trauma, Tissue, Thrombin — structure the differential, with Tone the most common.', null, 'Use the four Ts: Tone, Trauma, Tissue, Thrombin — in that order of frequency.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-ped-01', 'pediatrics', 1, 'A 2-year-old has a low-grade fever, a barking cough and inspiratory stridor that is worse at night. What is the most likely diagnosis?', 'У ребёнка 2 лет субфебрильная температура, «лающий» кашель и инспираторный стридор, усиливающийся ночью. Наиболее вероятный диагноз?', '[{"ru":"инспираторный стридор","en":"inspiratory stridor"},{"ru":"«лающий» кашель","en":"barking cough"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Acute epiglottitis', 'Острый эпиглоттит'), ('B', 'Croup (acute laryngotracheitis)', 'Острый стенозирующий ларинготрахеит (круп)'), ('C', 'Foreign body aspiration', 'Аспирация инородного тела'), ('D', 'Bronchial asthma', 'Бронхиальная астма')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'B', 'Croup (acute laryngotracheitis), usually caused by parainfluenza virus, presents in children aged roughly 6 months to 3 years with a barking cough, hoarseness and inspiratory stridor, often worse at night. Epiglottitis presents with high fever, drooling and a toxic appearance, usually without a barking cough.', null, 'The ''bark'' is the clue. A drooling, toxic child sitting forward should make you think epiglottitis instead.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-ped-02', 'pediatrics', 1, 'What is the most common cause of acute bronchiolitis in infants?', 'Какой возбудитель является наиболее частой причиной острого бронхиолита у детей первого года жизни?', '[{"ru":"бронхиолит","en":"bronchiolitis"},{"ru":"РС-вирус","en":"RSV"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Respiratory syncytial virus', 'Респираторно-синцитиальный вирус'), ('B', 'Streptococcus pneumoniae', 'Streptococcus pneumoniae'), ('C', 'Influenza B virus', 'Вирус гриппа B'), ('D', 'Mycoplasma pneumoniae', 'Mycoplasma pneumoniae')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'A', 'Respiratory syncytial virus is the most common cause of bronchiolitis in infants, with seasonal epidemics. Management is mainly supportive (oxygen, feeding support).', null, 'Bronchiolitis in an infant during winter epidemics: think RSV first.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-surg-01', 'surgery', 1, 'In a patient with suspected appendicitis, pressure in the left iliac fossa causes pain in the right iliac fossa. What is this sign called?', 'У пациента с подозрением на аппендицит надавливание в левой подвздошной области вызывает боль в правой подвздошной области. Как называется этот симптом?', '[{"ru":"подвздошная область","en":"iliac fossa"},{"ru":"симптом Ровзинга","en":"Rovsing''s sign"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Murphy''s sign', 'Симптом Мерфи'), ('B', 'Courvoisier''s sign', 'Симптом Курвуазье'), ('C', 'Rovsing''s sign', 'Симптом Ровзинга'), ('D', 'Kehr''s sign', 'Симптом Кера')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'C', 'Rovsing''s sign is pain in the right iliac fossa when the left iliac fossa is pressed, and is associated with appendicitis. Murphy''s sign relates to cholecystitis, Courvoisier''s sign to a distended gallbladder in malignant obstruction, and Kehr''s sign is referred left shoulder pain (e.g. splenic rupture).', null, 'Eponymous signs are high-yield for terminology: learn each one with its Russian name and the organ it points to.' from q;

with q as (insert into public.questions (slug, topic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-surg-02', 'surgery', 2, 'A 40-year-old woman has right upper quadrant pain and fever. During deep palpation under the right costal margin she stops inspiring because of pain. Which diagnosis does this sign suggest?', 'У женщины 40 лет боль в правом подреберье и лихорадка. При глубокой пальпации под правой рёберной дугой она прерывает вдох из-за боли. На какой диагноз указывает этот симптом?', '[{"ru":"правое подреберье","en":"right upper quadrant"},{"ru":"симптом Мерфи","en":"Murphy''s sign"}]'::jsonb, 'demo', 'MedPrep prototype demo set', 'owned', 'draft', null) returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Acute cholecystitis', 'Острый холецистит'), ('B', 'Acute pancreatitis', 'Острый панкреатит'), ('C', 'Right renal colic', 'Правосторонняя почечная колика'), ('D', 'Perforated duodenal ulcer', 'Перфоративная язва двенадцатиперстной кишки')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint) select q.id, 'A', 'Murphy''s sign — inspiratory arrest during palpation under the right costal margin — suggests acute cholecystitis. Fever and RUQ pain support the diagnosis; ultrasound is the first-line imaging.', null, 'Inspiratory arrest = the inflamed gallbladder moves down onto the examining hand.' from q;
